-- 19. Create Trigger for Prevent Negative Discount
DROP TRIGGER IF EXISTS dbo.trg_PreventNegativeDiscount;
GO
CREATE TRIGGER trg_PreventNegativeDiscount
ON [orders$]
AFTER INSERT
AS
BEGIN
    SET NOCOUNT ON;

    IF EXISTS (SELECT 1 FROM inserted WHERE discount < 0)
    BEGIN
        RAISERROR ('Discount cannot be negative', 16, 1);
        ROLLBACK TRANSACTION;
    END
END;

