  SELECT * FROM orders$ where order_id = 1014;

  -- 20. Triggger for Delivery Delay Warning
  CREATE TABLE DeliveryDelayLog (
    log_id INT PRIMARY KEY IDENTITY(1,1),
    order_id INT,
    customer_id INT,
    restaurant_id INT,
    delivery_time INT,
    created_at DATETIME DEFAULT GETDATE()
);
GO

-- SQL Server trigger: use the inserted table and set-based insert
CREATE TRIGGER dbo.logLateDeliveries
ON dbo.orders$
AFTER INSERT
AS
BEGIN
    SET NOCOUNT ON;

    INSERT INTO dbo.DeliveryDelayLog (order_id, customer_id, restaurant_id, delivery_time)
    SELECT i.order_id, i.customer_id, i.restaurant_id, i.delivery_time
    FROM inserted AS i
    WHERE i.delivery_time > 45;
END;
GO

